#include <stdio.h>
int countNumbersWithUniqueDigits(int n){
    if(n==0) return 1;
    int total=1, ways=1;
    for(int length=1; length<=n; ++length){
        if(length==1) ways=9;
        else ways*=11-length;
        total+=ways;
    }
    return total;
}

